<script setup lang="ts">
import { Link } from '@inertiajs/vue3';
import FormField from '@/Components/UI/FormField.vue';
import { useClosureWorkspace } from '@/composables/useClosureWorkspace';
import { calendarDateLabel, philippineTimestamp } from '@/utils/philippineTime';

const props = defineProps<{ caseId:number }>();
const emit = defineEmits<{updated: []}>();
const {data,selected,summary,busy,dirty,disabled,reconciliationRequired,error,fieldError,message,errorSummary,load,discard,view,write:save} = useClosureWorkspace(props.caseId);
async function write(action:'record'|'review'|'close'|'reopen') { if (await save(action)) emit('updated'); }
const labels:Record<string,string> = {high_or_critical_risk:'High or critical recorded risk',open_tasks:'Open case tasks',open_referrals:'Unfinished referrals',aftercare_required:'Required aftercare remains unfinished'};
const human = (value:string) => value.toLowerCase().replaceAll('_',' ');
const time = (value:string|null|undefined) => value ? philippineTimestamp(value) : 'Not recorded';
</script>

<template>
    <section aria-label="Closure and aftercare workspace" class="scroll-mt-24 space-y-5">
        <header class="rounded-lg border border-brand-200 bg-kalinga-lavender p-4">
            <div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="text-lg font-semibold text-brand-900">Closure & aftercare</h2><p class="mt-1 text-sm leading-6 text-slate-700">Review outcomes, retain the closure history and coordinate continuing support.</p></div><button type="button" class="ui-button" :disabled="busy" @click="load()">Refresh closure records</button></div>
            <p class="mt-3 text-xs leading-5 text-slate-700">Online entry only. Save before closing this page. New revisions require independent review; reopening preserves the former record and starts a new draft planning cycle.</p>
        </header>
        <div v-if="error" ref="errorSummary" role="alert" tabindex="-1" class="rounded-md border border-rose-300 bg-rose-50 p-4 text-sm text-rose-900">{{error}}</div>
        <p v-if="message" role="status" class="rounded-md border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-900">{{message}}</p>
        <div v-if="dirty||reconciliationRequired" class="rounded-md border border-amber-300 bg-kalinga-warm p-3 text-sm leading-6 text-amber-950"><p>{{reconciliationRequired?'Review the refreshed saved record below. Your unfinished revision is retained; discard it explicitly before using this refreshed snapshot.':'Unfinished closure revision retained on this page. Save online before closing, or cancel navigation to keep working.'}}</p><button type="button" class="ui-button mt-2" :disabled="busy" @click="discard">Discard unfinished revision</button></div>
        <p v-if="!data&&!error" role="status" class="ui-muted p-4">Loading authorized closure records...</p>
        <template v-if="data">
            <div class="grid items-start gap-5 xl:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]">
                <div class="min-w-0 space-y-5">
                    <section class="ui-panel overflow-hidden" aria-label="Current closure record"><header class="ui-panel-header bg-brand-50"><h3 class="ui-section-title">Current closure record</h3><span class="rounded border border-brand-200 bg-white px-2 py-1 text-xs capitalize text-brand-900">{{human(data.case.status)}}</span></header>
                        <div class="space-y-4 p-4 text-sm"><template v-if="data.current"><div class="flex flex-wrap gap-2 text-xs text-slate-600"><span>{{data.current.version?`Version ${data.current.version}`:'Surviving legacy record'}}</span><span>{{data.current.source==='authored_record'?'Authored record':'Legacy provenance - original recorded time may be unavailable'}}</span></div><p class="whitespace-pre-wrap break-words leading-6">{{data.current.summary||'Closure summary not recorded.'}}</p><dl class="grid gap-3 sm:grid-cols-2"><div><dt class="text-xs text-slate-600">Recorded by</dt><dd>{{data.current.author_name||(data.current.recorded_by?'Recorded user #'+data.current.recorded_by:'Author not recorded')}}<br><span class="text-xs text-slate-600">{{time(data.current.recorded_at)}}</span></dd></div><div><dt class="text-xs text-slate-600">Independent review</dt><dd>{{data.current.reviewed_at?(data.current.reviewer_name||'Recorded reviewer'):'Awaiting independent review'}}<br><span class="text-xs text-slate-600">{{time(data.current.reviewed_at)}}</span></dd></div></dl><p v-if="data.current.closed_at" class="text-xs text-slate-600">Closure recorded {{time(data.current.closed_at)}}</p></template><p v-else class="text-slate-600">No current closure record. Prior closure records remain available in history after reopening.</p>
                        <div v-if="data.projection_drift" class="rounded border border-amber-300 bg-kalinga-warm p-3"><p class="font-semibold">Surviving case text differs from the versioned record.</p><p class="mt-2 whitespace-pre-wrap break-words">{{data.surviving_projection?.summary||'No surviving summary text.'}}</p><p class="mt-2 text-xs">Original authorship of this difference is unknown. An authorized worker must record a revision before review, closing or reopening.</p></div>
                        <div class="flex flex-wrap gap-2"><button v-if="data.allowed_actions.review" type="button" :disabled="disabled||dirty" class="ui-button-primary" @click="write('review')">Review saved closure record</button><button v-if="data.allowed_actions.close" type="button" :disabled="disabled||dirty" class="ui-button-primary" @click="write('close')">Close reviewed case</button><button v-if="data.allowed_actions.reopen" type="button" :disabled="disabled||dirty" class="ui-button" @click="write('reopen')">Reopen case</button></div></div>
                    </section>
                    <form v-if="data.allowed_actions.record" class="ui-panel p-4" aria-labelledby="closure-revision-title" autocomplete="off" @submit.prevent="write('record')"><h3 id="closure-revision-title" class="ui-section-title">{{data.current?'Revise closure recommendation':'Record closure recommendation'}}</h3><p class="ui-muted mt-1">Record actual outcomes, closure basis, remaining risks and continuing support. Changes retain the previous version and clear its approval for this cycle.</p><fieldset :disabled="disabled" class="mt-4 space-y-4"><legend class="sr-only">Closure recommendation</legend><FormField id="closure-summary" label="Closure summary" :error="fieldError" required><textarea id="closure-summary" v-model="summary" required maxlength="5000" rows="7" class="ui-field"/></FormField><button type="submit" class="ui-button-primary" :disabled="!dirty">Save closure recommendation</button></fieldset></form>
                </div>
                <div class="min-w-0 space-y-5">
                    <section class="ui-panel p-4" aria-label="Closure readiness"><h3 class="ui-section-title">Readiness & continuing support</h3><p class="ui-muted mt-2">These checks reflect the current configured rules. They do not replace professional review or an approved local closure policy.</p><ul v-if="data.readiness.critical_blockers.length" class="mt-3 space-y-2"><li v-for="item in data.readiness.critical_blockers" :key="item.code" class="rounded border border-rose-300 bg-rose-50 p-3 text-sm text-rose-900">Blocks closing: {{labels[item.code]||human(item.code)}}</li></ul><ul v-if="data.readiness.warnings.length" class="mt-3 space-y-2"><li v-for="item in data.readiness.warnings" :key="item.code" class="rounded border border-amber-300 bg-kalinga-warm p-3 text-sm text-amber-950">Review: {{labels[item.code]||human(item.code)}}</li></ul><p v-if="!data.readiness.critical_blockers.length&&!data.readiness.warnings.length" class="mt-3 text-sm text-slate-700">No configured readiness flags are currently present. Independent closure review is still required.</p><p v-if="data.case.retention_review_at" class="mt-3 text-xs text-slate-600">Recorded retention review: {{time(data.case.retention_review_at)}}. This date is not a deletion instruction.</p><Link :href="route('cases.plans.workspace',caseId)+'?activity=continuity'" class="ui-button mt-4">Open aftercare & reintegration</Link>
                    <div class="mt-4 space-y-3"><h4 class="text-sm font-semibold">Recent continuity records</h4><article v-for="item in data.aftercare" :key="'a'+item.id" class="rounded border border-slate-200 p-3 text-sm"><p class="font-semibold">Aftercare - {{human(item.status)}}</p><p>{{item.responsible_office||'Office not recorded'}}</p><p class="mt-1 text-xs text-slate-600">Initial follow-up: {{item.initial_follow_up_at?calendarDateLabel(item.initial_follow_up_at):'Not recorded'}}</p></article><article v-for="item in data.reintegration" :key="'r'+item.id" class="rounded border border-slate-200 p-3 text-sm"><p class="font-semibold">Reintegration - {{human(item.status)}}</p><p>{{item.responsible_office||'Office not recorded'}}</p><p class="mt-1 text-xs text-slate-600">Target: {{item.target_date?calendarDateLabel(item.target_date):'Not recorded'}}</p></article><p v-if="!data.aftercare.length&&!data.reintegration.length" class="ui-muted">No continuity records recorded. Use the planning workspace when applicable.</p><p v-else class="text-xs text-slate-600">Up to five recent records per type. Open the planning workspace for the full continuity register.</p></div></section>
                </div>
            </div>
            <section class="ui-panel overflow-hidden" aria-label="Closure version history"><header class="ui-panel-header bg-brand-50"><h3 class="ui-section-title">Closure history</h3><span class="text-xs text-slate-600">{{data.history.total}} records</span></header><div class="grid gap-4 p-4 lg:grid-cols-2"><div class="space-y-2"><button v-for="record in data.history.data" :key="record.id!" type="button" class="flex min-h-11 w-full flex-wrap items-center justify-between gap-2 rounded-md border p-3 text-left text-sm" :class="selected?.id===record.id?'border-brand-600 bg-brand-50':'border-slate-200'" :disabled="busy" :aria-pressed="selected?.id===record.id" @click="view(record.id!)"><span class="font-semibold">Version {{record.version}} - {{record.source==='authored_record'?'Authored':'Legacy record'}}</span><span class="text-xs text-slate-600">{{record.closed_at?'Closed':record.superseded_at?'Prior revision':'Current'}} - {{time(record.recorded_at||record.created_at)}}</span></button><p v-if="!data.history.total" class="ui-muted">No versioned records yet. Surviving legacy text is retained when an authorized change is recorded.</p><div v-if="data.history.last_page>1" class="flex flex-wrap items-center gap-2 pt-2"><button type="button" class="ui-button" :disabled="busy||data.history.current_page===1" @click="load(data.history.current_page-1)">Previous versions</button><span class="text-xs">Page {{data.history.current_page}} of {{data.history.last_page}}</span><button type="button" class="ui-button" :disabled="busy||data.history.current_page===data.history.last_page" @click="load(data.history.current_page+1)">More versions</button></div></div><article v-if="selected" class="min-w-0 rounded-md border border-brand-200 bg-brand-50 p-4" aria-label="Selected historical closure record"><h4 class="font-semibold text-brand-900">Retained version {{selected.version}}</h4><p class="mt-3 whitespace-pre-wrap break-words text-sm leading-6">{{selected.summary||'Summary not recorded in this legacy record.'}}</p><p class="mt-3 text-xs text-slate-600">Recorded: {{time(selected.recorded_at)}}<br>Reviewed: {{time(selected.reviewed_at)}}<br>Closed: {{time(selected.closed_at)}}</p><p class="mt-3 text-xs leading-5 text-slate-700">Historical read-only record. Its review does not authorize closure of a later case cycle.</p></article><p v-else class="ui-muted self-start rounded-md border border-dashed border-slate-300 p-4">Select a version to read its retained summary. History lists contain metadata only.</p></div></section>
        </template>
    </section>
</template>
